from collections import deque
def getcomps(g):
 h,w=len(g),len(g[0]);seen=set(); cs=[]
 for r in range(h):
  for c in range(w):
   if not g[r][c] or (r,c) in seen: continue
   q=deque([(r,c)]);seen.add((r,c)); cc=[]
   while q:
    y,x=q.popleft();cc.append((y,x))
    for dy in (-1,0,1):
     for dx in (-1,0,1):
      n=(y+dy,x+dx)
      if (dy or dx) and 0<=n[0]<h and 0<=n[1]<w and g[n[0]][n[1]] and n not in seen: seen.add(n);q.append(n)
   cs.append(cc)
 return cs
